import { test, expect } from '@playwright/test'
import { installPublicPortalMocks } from './fixtures/public-portal-designs'

test.beforeEach(async ({ page }) => installPublicPortalMocks(page))

test('capture project summary two-per-row layout', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 })
  await page.goto('/#/UnifiedLogin?portal=projects', { waitUntil: 'domcontentloaded' })
  await expect(page.locator('.public-portal-screen')).toBeVisible()
  await expect(page.locator('.portal-skeleton')).toHaveCount(0)
  const rows = page.locator('.portal-table tbody tr')
  await expect(rows.first()).toBeVisible()
  // 进入第一条项目的楼幢列表
  await rows.first().getByRole('button', { name: '锦绣华府', exact: true }).click()
  await expect(page).toHaveURL(/view=buildings/)
  const summary = page.locator('.property-project-summary')
  await expect(summary).toBeVisible()
  await expect(summary).toContainText('锦绣华府')
  await summary.screenshot({ path: 'test-results/summary-1440.png' })
  // 打印关键布局信息
  const info = await page.evaluate(() => {
    const grid = document.querySelector('.property-summary-grid') as HTMLElement | null
    const items = Array.from(document.querySelectorAll('.property-summary-grid .property-summary-item')) as HTMLElement[]
    return {
      cols: grid ? getComputedStyle(grid).gridTemplateColumns : null,
      items: items.map(el => {
        const label = el.querySelector('.property-summary-label')?.textContent
        const valueEl = el.querySelector('.property-summary-value') as HTMLElement | null
        const rect = el.getBoundingClientRect()
        return {
          label,
          top: Math.round(rect.top),
          left: Math.round(rect.left),
          valueHeight: valueEl ? Math.round(valueEl.getBoundingClientRect().height) : null,
          lineHeight: valueEl ? getComputedStyle(valueEl).lineHeight : null,
          text: valueEl?.textContent?.trim(),
        }
      }),
    }
  })
  console.log('SUMMARY_INFO=' + JSON.stringify(info, null, 2))
})

